import {
  SITE_URL,
  BASE_TITLE,
  DEFAULT_DESCRIPTION,
} from "@/constants/routeMeta";

function setMetaTag(name, content, attr = "name") {
  let el = document.querySelector(`meta[${attr}="${name}"]`);
  if (!el) {
    el = document.createElement("meta");
    el.setAttribute(attr, name);
    document.head.appendChild(el);
  }
  el.setAttribute("content", content);
}

function setCanonical(href) {
  let el = document.querySelector('link[rel="canonical"]');
  if (!el) {
    el = document.createElement("link");
    el.setAttribute("rel", "canonical");
    document.head.appendChild(el);
  }
  el.setAttribute("href", href);
}

/**
 * title / description / canonical / og:* をまとめて更新する。
 * router.afterEach（ルート共通メタ）と BlogDetailView（記事別メタ）の両方から使う。
 * 静的生成側（scripts/generate-seo-pages.js）と出力形式を揃えること。
 *
 * type: og:type。通常ページは "website"、ブログ記事は "article" を渡す。
 */
export function updateMeta({ title, description, path, type = "website" }) {
  const pageTitle = title ? `${title} | ${BASE_TITLE}` : BASE_TITLE;
  const desc = description || DEFAULT_DESCRIPTION;
  const url = SITE_URL + path;

  document.title = pageTitle;
  setMetaTag("description", desc);
  setMetaTag("og:title", pageTitle, "property");
  setMetaTag("og:description", desc, "property");
  setMetaTag("og:url", url, "property");
  setMetaTag("og:type", type, "property");
  setCanonical(url);
}
